"""Checks for Assignment 09.

The course keeps these checks in 09/assignment_checks/, which the assignment
workflow downloads on every push, and the handout ships a byte-identical copy
so a local run reports exactly what GitHub will. They read the six CSV files a
submission saves in output/ and compare them with values frozen below from the
supplied data/*.parquet files. scripts/build_assignment09_data.py writes the
data and that block together, so the two always agree.

Each check scores one thing, so one mistake costs only its own points, and no
check waits for another to pass. Values are compared after parsing: spacing,
line endings, quoting, a byte-order mark, column order, row order, row-number
columns, number formatting (2 == 2.0 == 2.00), and the letter case of labels
and headers never cost points, and cells may be separated by commas,
semicolons, or tabs. A date may be written with or without its time and
offset. A mistake is charged once: a value column the file does not hold costs
only its columns check, and so does one saved under another name with the right
values. The heart-rate features of Task 3.2 also accept hourly means, so a
median/mean slip costs points only in Task 2.2, and the holdout summary of
Task 3.3 also accepts counts worked out from the student's own Task 3.2 file.

Nothing here imports, runs, or inspects student code.
"""

