# Means may be saved with every digit or rounded to one decimal.
TOLERANCE = 0.06
# Ways pandas and people write an empty cell.
MISSING_SPELLINGS = frozenset({"", "nan", "na", "n/a", "none", "null", "<na>", "nat"})
# A cell the checks do not compare: a last_lactate whose lab result time was set aside as NaT.
SKIP = "skip"


def _label(cell: str) -> str:
    """A label compared in any letter case, with spaces or hyphens for underscores: 'Later holdout' is later_holdout."""
    return re.sub(r"[\s-]+", "_", " ".join(cell.split()).casefold())


DATE_FORMATS = ("%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d %b %Y", "%d %B %Y", "%b %d %Y", "%B %d %Y")


def _date(cell: str) -> str:
    """A calendar date as YYYY-MM-DD, ignoring any time and offset after it, or the label itself."""
    text = " ".join(cell.split())
    match = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})(?=$|[ T])", text)
    if match:
        return "-".join((match.group(1), match.group(2).zfill(2), match.group(3).zfill(2)))
    head = re.split(r"[ T](?=\d{1,2}:)", text, maxsplit=1)[0].replace(",", "")
    for pattern in DATE_FORMATS:
        try:
            return datetime.strptime(head, pattern).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return _label(text)


@dataclass(frozen=True)
class Artifact:
    """One saved CSV: where it lives, which task writes it, and what it should hold.

    `rows` maps each required key, a tuple of the key columns' values, to the
    expected value of every other column; None means an empty cell and SKIP a
    cell that is not compared. `alternatives` maps a key to other values a
    column may hold, such as a feature built from hourly means. `form` turns a
    saved key cell into the form the keys are written in.
    """

    path: str
    task: str
    columns: tuple[str, ...]
    key: tuple[str, ...]
    rows: dict[tuple[str, ...], dict[str, object]]
    alternatives: dict[tuple[str, ...], dict[str, object]] = field(default_factory=dict)
    form: Callable[[str], str] = _label


@dataclass(frozen=True)
class Table:
    """A saved CSV: its casefolded column names and one {column: cell} dict per data row.

    `written` maps each casefolded column name to the header as the file wrote
    it, for messages.
    """

    columns: tuple[str, ...]
    rows: tuple[dict[str, str], ...]
    written: dict[str, str] = field(default_factory=dict)
    conflicting_columns: tuple[str, ...] = ()

    def header(self, columns=None) -> str:
        """The named columns (all of them by default) as the file wrote them: 'readings and episodes'."""
        shown = [self.written.get(column, column) or "a column with no header"
                 for column in (self.columns if columns is None else columns)]
        return _join(shown) or "none"


@dataclass(frozen=True)
class Check:
    name: str
    action: Callable[[Path], None]


DAILY_TABLE = Artifact(
    path="output/daily_feed.csv",
    task="Task 1.2",
    columns=("date", "readings", "episodes"),
    key=("date",),
    rows={(day,): {"readings": readings, "episodes": episodes} for day, (readings, episodes, _) in DAILY_FEED.items()},
    # UTC days cost the readings check; episodes counted on them are not charged again.
    alternatives={(day,): {"episodes": episodes} for day, (_, episodes) in DAILY_FEED_UTC.items()},
    form=_date,
)

COVERAGE_COLUMNS = ("grid_hours", "gap_hours", "gap_runs", "longest_gap_h")
