FEATURE_COLUMNS = ("prev_hour_hr", "mean_prev_6h", "last_lactate")
FEATURES_TABLE = Artifact(
    path="output/score_features.csv",
    task="Task 3.2",
    columns=("episode_id", *FEATURE_COLUMNS),
    key=("episode_id",),
    rows={(episode,): {"prev_hour_hr": prev, "mean_prev_6h": mean_6h, "last_lactate": SKIP if unsure else lactate}
          for episode, (_, _, prev, mean_6h, _, _, lactate, unsure, _) in FEATURES.items()},
    # Hourly means cost Task 2.2's checks, and lab clocks localized as UTC cost Task 3.1's timed_results check.
    alternatives={(episode,): {"prev_hour_hr": prev, "mean_prev_6h": mean_6h, "last_lactate": utc_lactate}
                  for episode, (_, _, _, _, prev, mean_6h, _, _, utc_lactate) in FEATURES.items()},
)


def _holdout(mean_6h: Callable[[str], object]) -> dict[tuple[str, ...], dict[str, object]]:
    """The Task 3.3 counts per block, flagging an episode when mean_6h(episode) is at least FLAG_BPM."""
    rows = {}
    for episode, (block, escalated, *_) in FEATURES.items():
        counts = rows.setdefault((block,), dict.fromkeys(HOLDOUT_COLUMNS, 0))
        value = mean_6h(episode)
        flagged = isinstance(value, (int, float)) and value >= FLAG_BPM
        counts["episodes"] += 1
        counts["escalations"] += escalated
        counts["flagged"] += flagged
        counts["flagged_escalations"] += flagged and escalated
    return rows


HOLDOUT_COLUMNS = ("episodes", "escalations", "flagged", "flagged_escalations")
HOLDOUT_TABLE = Artifact(
    path="output/holdout_summary.csv",
    task="Task 3.3",
    columns=("block", *HOLDOUT_COLUMNS),
    key=("block",),
    rows=_holdout(lambda episode: FEATURES[episode][3]),
    alternatives=_holdout(lambda episode: FEATURES[episode][5]),
)

ARTIFACTS = (DAILY_TABLE, COVERAGE_TABLE, RULES_TABLE, TURNAROUND_TABLE, FEATURES_TABLE, HOLDOUT_TABLE)


def _assert(condition: object, message: str) -> None:
    if not condition:
        raise AssertionError(message)


def _join(items) -> str:
    items = [str(item) for item in items]
    if len(items) <= 1:
        return "".join(items)
    return ", ".join(items[:-1]) + " and " + items[-1]


def _listed(problems: list[str], limit: int = 4) -> str:
    shown = "; ".join(problems[:limit])
    if len(problems) > limit:
        shown += f"; and {len(problems) - limit} more like {'it' if len(problems) - limit == 1 else 'them'}"
    return shown


def _clean(cell: str) -> str:
    return " ".join(cell.split())


def _fold(column: str) -> str:
    return _clean(column).casefold()


def _number(cell: str) -> float | None:
    try:
        number = float(_clean(cell).replace(",", ""))
    except ValueError:
        return None
    return number if math.isfinite(number) else None


def _is_whole_number(cell: str) -> bool:
    number = _number(cell)
    return number is not None and number.is_integer()


def _matches(cell: str, expected: object) -> bool:
    text = _clean(cell)
    if expected is SKIP:
        return True
    if expected is None:
        return text.casefold() in MISSING_SPELLINGS
    if isinstance(expected, (int, float)):
        number = _number(text)
        return number is not None and abs(number - expected) <= TOLERANCE
    return _label(text) == _label(str(expected))


def _show(value: object) -> str:
    if value is None:
        return "blank"
    if isinstance(value, float):
        return f"{round(value, 2):g}"
    return str(value)


def _given(cell: str) -> str:
    text = _clean(cell)
    return text if text else "blank"


def _some(names: list[str], limit: int = 4) -> str:
    """The first few names, then how many more: 'H00001, H00002, H00003, H00004 and 180 more'."""
    if len(names) <= limit + 1:
        return _join(names)
    return f"{', '.join(names[:limit])} and {len(names) - limit} more"


def _key_name(key: tuple[str, ...]) -> str:
    return " ".join(key)


def _expected_keys(names: list[str]) -> str:
    """The expected row keys, shortened past six: 'H00001, H00002, H00003, ... and H01400 (1400 in all)'."""
    if len(names) <= 6:
        return _join(names)
    return f"{', '.join(names[:3])}, ... and {names[-1]} ({len(names)} in all)"


def _decode(raw: bytes) -> str:
    """An artifact's text without a byte-order mark; UTF-16 is read through its mark."""
    if raw.startswith((codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE)):
        try:
            return raw.decode("utf-16")
        except UnicodeDecodeError:
            pass
    return raw.decode("utf-8", errors="replace").lstrip("﻿")


# A CSV may separate its cells with commas, semicolons, or tabs.
DELIMITERS = (",", ";", "\t")
# A number written with a decimal comma, as a spreadsheet set to a European locale saves it: 12,5 is 12.5.
DECIMAL_COMMA = re.compile(r"^(\s*[+-]?\d*),(\d+\s*)$")


def _csv_rows(text: str) -> list[list[str]]:
    """The rows of a saved CSV, blank lines left out, split on the separator its header line uses.

    Commas, semicolons, and tabs are all accepted: whichever splits the header
    line into the most cells is used, and a tie keeps commas. A file separated
    by semicolons may write decimal commas, so there 12,5 reads as 12.5.
    """
    if "\x00" in text:
        raise csv.Error("file contains a NUL byte instead of CSV text")
    lines = text.splitlines()
    header = next((line for line in lines if line.strip()), "")
    delimiter = max(DELIMITERS, key=lambda mark: len(next(csv.reader([header], delimiter=mark), [])))
    rows = [row for row in csv.reader(lines, delimiter=delimiter) if any(cell.strip() for cell in row)]
    if delimiter == ";":
        rows = [[DECIMAL_COMMA.sub(r"\1.\2", cell) for cell in row] for row in rows]
    return rows


def _artifact_path(root: Path, name: str) -> Path | None:
    """The artifact's path, matching its file name in any letter case, or None.

    macOS and Windows disks ignore letter case, so matching in any case makes a
    local run there agree with GitHub's Linux runner.
    """
    path = root / name
    if path.is_file() and not path.is_symlink():
        return path
    if not path.parent.is_dir():
        return None
    same_name = [
        other
        for other in path.parent.iterdir()
        if other.name.casefold() == path.name.casefold() and other.is_file() and not other.is_symlink()
    ]
    return same_name[0] if len(same_name) == 1 else None


def _missing(root: Path, artifact: Artifact) -> str:
    """Say the artifact is missing, naming any saved file whose name looks like a typo of its name."""
    message = f"{artifact.path} is missing; run the {artifact.task} cell to write it, then commit it."
    wanted = root / artifact.path
    required = {Path(other.path).name.casefold() for other in ARTIFACTS}
    if wanted.parent.is_dir():
        look_alikes = sorted(
            path.relative_to(root).as_posix()
            for path in wanted.parent.iterdir()
            if path.is_file()
            and path.name.casefold() not in required
            and difflib.SequenceMatcher(None, wanted.name.casefold(), path.name.casefold()).ratio() >= 0.75
        )
        if look_alikes:
            message += f" Found {_join(look_alikes)}; save it as {artifact.path} instead."
    return message


def _is_index_header(cell: str) -> bool:
    return cell in ("", "index") or cell.startswith("unnamed") or re.fullmatch(r"level_\d+", cell) is not None


def read_table(root: Path, artifact: Artifact) -> Table:
    """Parse a saved CSV, however it is separated, spaced, quoted, or ended.

    A column headed by nothing, `Unnamed: 0`, `index`, or `level_1` that holds
    only whole numbers is the row numbers pandas writes when `index=False` is
    left out, so it is set aside rather than counted as a column. So is an
    empty column with no header, which a trailing comma on every line makes.
    """
    path = _artifact_path(root, artifact.path)
    _assert(path is not None, _missing(root, artifact))
    try:
        lines = _csv_rows(_decode(path.read_bytes()))
    except csv.Error as error:
        raise AssertionError(
            f"{artifact.path} cannot be read as a CSV table ({error}); run the {artifact.task} cell again so "
            "to_csv() writes it, then compare it with the checkpoint in README.md."
        ) from None
    _assert(lines, f"{artifact.path} is empty; run the {artifact.task} cell again to write it.")
    written = [_clean(cell) for cell in lines[0]]
    body = [[_clean(cell) for cell in row] for row in lines[1:]]
    width = max(len(written), *(len(row) for row in body)) if body else len(written)
    written += [""] * (width - len(written))
    body = [row + [""] * (width - len(row)) for row in body]

    header = [cell.casefold() for cell in written]
    numbers = [
        i for i, column in enumerate(header)
        if _is_index_header(column) and body and all(_is_whole_number(row[i]) for row in body)
    ]
    keep = [
        i for i, column in enumerate(header)
        if (column or any(row[i] for row in body)) and (i not in numbers or len(numbers) == len(header))
    ]
    written, header = [written[i] for i in keep], [header[i] for i in keep]
    body = [[row[i] for i in keep] for row in body]

    rows = []
    conflicting = set()
    for row in body:
        values: dict[str, str] = {}
        for i, column in enumerate(header):
            cell = row[i]
            if values.get(column) and cell:
                first_number, next_number = _number(values[column]), _number(cell)
                equal = (
                    abs(first_number - next_number) <= TOLERANCE
                    if first_number is not None and next_number is not None
                    else values[column].casefold() == cell.casefold()
                )
                if not equal:
                    conflicting.add(column)
            if not values.get(column):
                values[column] = cell
        rows.append(values)
    names: dict[str, str] = {}
    for column, as_written in zip(header, written):
        names.setdefault(column, as_written)
    return Table(columns=tuple(dict.fromkeys(header)), rows=tuple(rows), written=names,
                 conflicting_columns=tuple(sorted(conflicting)))


def _expected_values(artifact: Artifact, key: tuple[str, ...], column: str) -> list[object]:
    """The values a cell may hold: the expected one, then any alternative."""
    values = [artifact.rows[key][column]]
    other = artifact.alternatives.get(key, {})
    if column in other:
        values.append(other[column])
    return values


def _holds(grouped, artifact: Artifact, saved: str, column: str) -> bool:
    """True when every row's `saved` cell holds `column`'s expected value, and one of them is not blank."""
    filled = False
    for key, rows in grouped.items():
        allowed = _expected_values(artifact, key, column)
        for row in rows:
            if not any(_matches(row[saved], value) for value in allowed):
                return False
            filled = filled or any(value not in (None, SKIP) for value in allowed)
    return filled


def _resolve(table: Table, artifact: Artifact) -> dict[str, str]:
    """Map each expected column to the saved column that holds it.

    A column saved under its own name, in any letter case, is found by name. A
    key column saved under another name, such as a blank header over saved
    index labels, is found by its values. An unexpected column whose values
    match one unplaced value column is taken to hold it. If exactly one
    expected value column is still unplaced and exactly one unexpected column is
    left, that column is taken to hold it. A misnamed column then costs only
    the columns check, or its values check too when its values are wrong.
    """
    expected = [_fold(column) for column in artifact.columns]
    found = {column: _fold(column) for column in artifact.columns if _fold(column) in table.columns}
    spare = [column for column in table.columns if column not in expected]
    for position, column in enumerate(artifact.key):
        if column in found:
            continue
        wanted = {artifact.form(key[position]) for key in artifact.rows}
        candidates = []
        for other in spare:
            values = [artifact.form(row[other]) for row in table.rows if row[other]]
            if values and sum(value in wanted for value in values) * 2 > len(values):
                candidates.append(other)
        if len(candidates) == 1:
            found[column] = candidates[0]
            spare.remove(candidates[0])
    # A key column is only ever found by name or by its values, never by elimination.
    unplaced = [column for column in artifact.columns if column not in found and column not in artifact.key]
    if unplaced and spare:
        try:
            grouped, _ = _group(table, artifact, found)
        except AssertionError:
            grouped = {}
        matches = {other: [column for column in unplaced if _holds(grouped, artifact, other, column)] for other in spare}
        # Pair only one-to-one matches: a spare column that fits two expected columns places neither.
        for other, columns in matches.items():
            if len(columns) == 1 and sum(columns[0] in fits for fits in matches.values()) == 1:
                found[columns[0]] = other
        spare = [column for column in spare if column not in found.values()]
        unplaced = [column for column in unplaced if column not in found]
    if len(unplaced) == 1 and len(spare) == 1:
        found[unplaced[0]] = spare[0]
    return found


def _describe(row: dict[str, str], columns: list[str]) -> str:
    return "a row reading " + ", ".join(_given(row[column]) for column in columns)


def _group(table: Table, artifact: Artifact, found: dict[str, str]):
    """({expected key: [rows]}, [rows naming no expected key]) for the saved table.

    When every key column is saved, each row is matched by its key. When one is
    not, as when the key stayed in the index and was dropped by `index=False`,
    each row is matched by the values it does hold, so the lost column costs
    the columns check alone.
    """
    grouped: dict[tuple[str, ...], list[dict[str, str]]] = {}
    unknown = []
    if all(column in found for column in artifact.key):
        canonical = {tuple(artifact.form(part) for part in key): key for key in artifact.rows}
        for row in table.rows:
            cells = tuple(artifact.form(row[found[column]]) for column in artifact.key)
            key = canonical.get(cells)
            if key is None:
                unknown.append("a row for " + " ".join(row[found[column]] or "blank" for column in artifact.key))
            else:
                grouped.setdefault(key, []).append(row)
        return grouped, unknown

    values = [column for column in artifact.columns if column not in artifact.key and column in found]
    absent = [column for column in artifact.key if column not in found]
    _assert(
        values,
        f"{artifact.path} has no {_join(absent)} column (its columns are {table.header()}), "
        f"so its rows cannot be matched; {artifact.task} saves the header line {','.join(artifact.columns)}.",
    )
    for row in table.rows:
        candidates = [
            key
            for key in artifact.rows
            if all(any(_matches(row[found[column]], value) for value in _expected_values(artifact, key, column))
                   for column in values)
        ]
        if len(candidates) == 1:
            grouped.setdefault(candidates[0], []).append(row)
        else:
            unknown.append(_describe(row, [found[column] for column in artifact.columns if column in found]))
    return grouped, unknown


def columns_check(artifact: Artifact, hint: str) -> Callable[[Path], None]:
    """The saved header holds exactly the expected columns, in any order."""

    def check(root: Path) -> None:
        table = read_table(root, artifact)
        found = _resolve(table, artifact)
        # A saved index with no name leaves its column unheaded; holding the keys, it is the key column.
        first = table.columns[0] if table.columns else None
        unheaded = {
            column: found[column]
            for column in artifact.key
            if _fold(column) not in table.columns and first is not None and found.get(column) == first
            and _is_index_header(first)
        }
        expected = [_fold(column) for column in artifact.columns]
        missing = [column for column in artifact.columns if _fold(column) not in table.columns and column not in unheaded]
        extra = [column for column in table.columns if column not in expected and column not in unheaded.values()]
        problems = []
        if missing:
            problems.append(f"is missing {_join(missing)}")
        if extra:
            problems.append(f"also has {table.header(extra)}")
        _assert(
            not problems,
            f"{artifact.path} " + " and ".join(problems) + f"; {artifact.task} saves the header line "
            f"{','.join(artifact.columns)} (any column order). {hint}",
        )

    return check


def rows_check(artifact: Artifact, hint: str) -> Callable[[Path], None]:
    """Each required key appears on exactly one row, and no unexpected key appears."""

    def check(root: Path) -> None:
        table = read_table(root, artifact)
        found = _resolve(table, artifact)
        _assert(
            not any(found.get(column) in table.conflicting_columns for column in artifact.key),
            f"{artifact.path} has repeated key headers with conflicting labels; expected one key value per "
            f"row. Remove the extra key column and save {artifact.task}'s table again.",
        )
        grouped, unknown = _group(table, artifact, found)
        missing = [key for key in artifact.rows if key not in grouped]
        repeated = [key for key, rows in grouped.items() if len(rows) > 1]
        problems = []
        if missing:
            problems.append(f"is missing {_some([_key_name(key) for key in missing])}")
        if repeated:
            problems.append("lists " + _some([f"{_key_name(key)} {len(grouped[key])} times" for key in repeated]))
        if unknown:
            shown = _join(unknown[:4]) + (f" and {len(unknown) - 4} more" if len(unknown) > 4 else "")
            problems.append(f"also has {shown}")
        _assert(
            not problems,
            f"{artifact.path} " + "; ".join(problems) + f"; it should hold one row for each of "
            f"{_expected_keys([_key_name(key) for key in artifact.rows])}. Fix it in {artifact.task}: {hint}",
        )

    return check


def values_check(
    artifact: Artifact,
    columns: tuple[str, ...],
    hint: str,
    cause: Callable[[Path, Table, dict[str, str]], str] | None = None,
    own: Callable[[Path], dict[tuple[str, ...], dict[str, object]]] | None = None,
) -> Callable[[Path], None]:
    """Every saved row for an expected key holds the expected values in `columns`.

    A missing or repeated row costs the rows check, not this one: this check
    compares whatever rows the file does hold for the expected keys. An
    expected column the file does not hold is charged once, by the columns
    check, so this check compares only the columns it can place, unless a
    spare column is left that could have held it: then its values are wrong
    too. `own(root)` gives values worked out from the student's own earlier
    artifact, also accepted, so an earlier mistake costs points only once.
    `cause(root, table, found)` names a likely cause, or returns "".
    """

    def check(root: Path) -> None:
        table = read_table(root, artifact)
        found = _resolve(table, artifact)
        present = tuple(column for column in columns if column in found)
        conflicts = [column for column in present if found.get(column) in table.conflicting_columns]
        _assert(
            not conflicts,
            f"{artifact.path} has repeated {_join(conflicts)} headers with conflicting values; expected one "
            f"value per column on each row. Remove the extra columns and save {artifact.task}'s table again.",
        )
        grouped, unknown = _group(table, artifact, found)
        held = [f"a row for {_key_name(key)}" for key in grouped] + unknown
        holds = ", ".join(held[:3]) + f" and {len(held) - 3} more" if len(held) > 3 else _join(held) or "no data rows"
        _assert(
            grouped,
            f"{artifact.path} has no row for any of {_expected_keys([_key_name(key) for key in artifact.rows])} "
            f"(it holds {holds}), so its {_join(columns)} values cannot be compared; the rows check says what to "
            f"fix in {artifact.task}.",
        )
        derived = own(root) if own else {}
        wrong = []
        for key, rows in grouped.items():
            for column in present:
                allowed = _expected_values(artifact, key, column)
                if column in derived.get(key, {}):
                    allowed.append(derived[key][column])
                given = {_given(row[found[column]]) for row in rows
                         if not any(_matches(row[found[column]], value) for value in allowed)}
                if given:
                    wrong.append(f"{_key_name(key)} has {column} {_join(sorted(given))}, "
                                 f"expected {_show(artifact.rows[key][column])}")
        # A column left out is charged once, by the columns check. One renamed with values that match nothing stays
        # unplaced beside a spare column: its wrong values are a second mistake, charged here.
        expected_names = {_fold(name) for name in artifact.columns}
        spare = [name for name in table.columns if name not in found.values() and name not in expected_names]
        for column in columns if spare else ():
            first = next((key for key in artifact.rows if key in grouped
                          and artifact.rows[key][column] not in (None, SKIP)), None)
            if column not in found and first is not None:
                wrong.append(
                    f"no saved column holds {column}: {table.header(spare)} does not match it (expected {column} "
                    f"{_show(artifact.rows[first][column])} for {_key_name(first)}, for example)"
                )
        note = cause(root, table, found) if cause and wrong else ""
        _assert(
            not wrong,
            f"{artifact.path}: " + _listed(wrong) + "." + (f" {note}" if note else "") + f" Fix it in {artifact.task}: {hint}",
        )

    return check


def _saved(table: Table, found: dict[str, str], artifact: Artifact, column: str) -> dict[tuple[str, ...], str]:
    """{key: the saved cell in `column`} for the rows whose key is saved once."""
    if column not in found or not all(name in found for name in artifact.key):
        return {}
    canonical = {tuple(artifact.form(part) for part in key): key for key in artifact.rows}
    cells: dict[tuple[str, ...], list[str]] = {}
    for row in table.rows:
        key = canonical.get(tuple(artifact.form(row[found[name]]) for name in artifact.key))
        if key is not None:
            cells.setdefault(key, []).append(row[found[column]])
    return {key: saved[0] for key, saved in cells.items() if len(saved) == 1}


def _utc_days(root: Path, table: Table, found: dict[str, str]) -> str:
    """When the saved dates carry a +00:00 or Z offset, say the days were drawn in UTC."""
    column = found.get("date")
    cells = [row[column] for row in table.rows] if column else []
    if cells and any(re.search(r"(\+00:?00|Z|UTC)$", _clean(cell)) for cell in cells):
        return ("The saved dates carry a UTC offset (+00:00), so each bin is a UTC day, which starts at 19:00 or "
                "20:00 the evening before in New York; convert recorded_at to America/New_York before resample(\"D\").")
    return ""


def _counted_heart_rates(root: Path, table: Table, found: dict[str, str]) -> str:
    """When the saved readings are the non-missing heart rates, say count() skipped the rows with no heart rate."""
    saved = _saved(table, found, DAILY_TABLE, "readings")
    if saved and all(_matches(cell, DAILY_FEED[key[0]][2]) for key, cell in saved.items()):
        return ('These are the rows with a heart rate: count() skips the rows the patch sent with none. The feed '
                'audit counts every row it received, so use "size".')
    return ""


def _hourly_means(root: Path, table: Table, found: dict[str, str]) -> str:
    """When the saved rule counts are the ones hourly means give, say to take medians."""
    for column in RULE_COLUMNS:
        saved = _saved(table, found, RULES_TABLE, column)
        position = RULE_COLUMNS.index(column)
        if saved and all(_matches(cell, ALERT_RULES_MEAN[key[0]][position]) for key, cell in saved.items()) \
                and any(not _matches(cell, ALERT_RULES[key[0]][position]) for key, cell in saved.items()):
            return "These counts come from hourly means; the hourly table takes each hour's median."
    return ""


def _own_holdout(root: Path) -> dict[tuple[str, ...], dict[str, object]]:
    """The Task 3.3 counts worked out from the student's own output/score_features.csv, or {} if unreadable."""
    try:
        table = read_table(root, FEATURES_TABLE)
        found = _resolve(table, FEATURES_TABLE)
    except (AssertionError, OSError, ValueError, csv.Error):
        return {}
    if "mean_prev_6h" not in found:
        return {}
    saved = _saved(table, found, FEATURES_TABLE, "mean_prev_6h")
    if not saved:
        return {}
    rows = {}
    for (episode,), cell in saved.items():
        block, escalated = FEATURES[episode][:2]
        counts = rows.setdefault((block,), dict.fromkeys(HOLDOUT_COLUMNS, 0))
        value = _number(cell)
        flagged = value is not None and value >= FLAG_BPM
        counts["episodes"] += 1
        counts["escalations"] += escalated
        counts["flagged"] += flagged
        counts["flagged_escalations"] += flagged and escalated
    return rows


CHECKS = (
    # Task 1.2: output/daily_feed.csv
    Check("daily feed: columns", columns_check(
        DAILY_TABLE,
        'Name the two summaries in .agg() (readings=..., episodes=...), then reset_index() and rename the '
        'recorded_at column to date.')),
    Check("daily feed: one row per New York day", rows_check(
        DAILY_TABLE,
        f'resample("D") on the New York clock gives one row per calendar day from {min(DAILY_FEED)} to '
        f'{max(DAILY_FEED)}, {len(DAILY_FEED)} in all.')),
    Check("daily feed: readings values", values_check(
        DAILY_TABLE, ("readings",),
        'readings is ("heart_rate", "size"): every row the feed sent that New York day, with or without a heart rate.',
        cause=lambda root, table, found: _utc_days(root, table, found) or _counted_heart_rates(root, table, found))),
    Check("daily feed: episodes values", values_check(
        DAILY_TABLE, ("episodes",),
        'episodes is ("episode_id", "nunique"): each episode that sent a reading that day counts once.',
        cause=_utc_days)),
    # Task 2.1: output/episode_coverage.csv
    Check("episode coverage: columns", columns_check(
        COVERAGE_TABLE, "Join the per-episode hour counts and gap-run summaries, then reset_index().")),
    Check("episode coverage: one row per episode", rows_check(
        COVERAGE_TABLE,
        f"keep every episode, {len(COVERAGE)} in all, including those with no gap (their gap_runs and "
        "longest_gap_h are 0).")),
    Check("episode coverage: grid_hours and gap_hours values", values_check(
        COVERAGE_TABLE, ("grid_hours", "gap_hours"),
        'grid_hours counts the rows of the episode\'s hourly grid from resample("h").count() (first reading\'s hour to '
        "last), and gap_hours the hours on it with no reading (count a column every row fills, such as source_row).")),
    Check("episode coverage: gap_runs and longest_gap_h values", values_check(
        COVERAGE_TABLE, ("gap_runs", "longest_gap_h"),
        "Number the runs with a grouped cumsum() of source_observed, count each run's hours, then take the count "
        "and max() per episode; an episode with no gap has 0 for both, not a blank.")),
    # Task 2.2: output/alert_rules.csv
    Check("alert rules: columns", columns_check(
        RULES_TABLE, "Build the three-row table with the columns rule, episodes_flagged, and escalations_flagged.")),
    Check("alert rules: one row per rule", rows_check(
        RULES_TABLE, "one row each for any_reading, hourly_median, and rolling_3h.")),
    Check("alert rules: episodes_flagged values", values_check(
        RULES_TABLE, ("episodes_flagged",),
        f"episodes_flagged counts the episodes whose highest value under the rule is at least {ALERT_BPM} (>=).",
        cause=_hourly_means)),
    Check("alert rules: escalations_flagged values", values_check(
        RULES_TABLE, ("escalations_flagged",),
        "escalations_flagged counts the flagged episodes whose outcome is escalated.", cause=_hourly_means)),
    # Task 3.1: output/lab_turnaround.csv
    Check("lab turnaround: columns", columns_check(
        TURNAROUND_TABLE, 'Group by "test" with as_index=False and name the three summaries in .agg().')),
    Check("lab turnaround: one row per test", rows_check(
        TURNAROUND_TABLE, "one row per test: BMP, BNP, CBC, INR, and Lactate.")),
    Check("lab turnaround: orders and timed_results values", values_check(
        TURNAROUND_TABLE, ("orders", "timed_results"),
        'orders is ("test", "size"), every row; timed_results is ("resulted_at", "count"), which skips the results '
        'set aside as NaT by tz_localize(..., ambiguous="NaT", nonexistent="NaT").')),
    Check("lab turnaround: median_turnaround_h values", values_check(
        TURNAROUND_TABLE, ("median_turnaround_h",),
        "median_turnaround_h is the median of (resulted_at - collected_at) in hours, .dt.total_seconds() / 3600.")),
    # Task 3.2: output/score_features.csv
    Check("score features: columns", columns_check(
        FEATURES_TABLE, "Keep episode_id and the three features, without the hourly timestamps or the outcome.")),
    Check("score features: one row per scored episode", rows_check(
        FEATURES_TABLE,
        f"keep the hourly row at each episode's prediction time, the admission hour (dt.floor(\"h\")) plus "
        f"24 hours; {len(FEATURES)} episodes still had readings then.")),
    Check("score features: prev_hour_hr values", values_check(
        FEATURES_TABLE, ("prev_hour_hr",),
        "prev_hour_hr is the grouped shift(1) of the hourly heart rate: the hour before the prediction time, blank "
        "when that hour had no reading.")),
    Check("score features: mean_prev_6h values", values_check(
        FEATURES_TABLE, ("mean_prev_6h",),
        "mean_prev_6h is a grouped shift(1) followed by rolling(6, min_periods=1).mean(): the six hours before the "
        "prediction time, never the prediction hour itself.")),
    Check("score features: last_lactate values", values_check(
        FEATURES_TABLE, ("last_lactate",),
        "last_lactate is the value of the latest lactate whose resulted_at (in UTC) is at or before the prediction "
        "time, blank when none was; the lab times must be localized to America/New_York before tz_convert(\"UTC\").")),
    # Task 3.3: output/holdout_summary.csv
    Check("holdout summary: columns", columns_check(
        HOLDOUT_TABLE, 'Group the scored episodes by "block" with as_index=False and name the four sums in .agg().')),
    Check("holdout summary: one row per block", rows_check(
        HOLDOUT_TABLE, 'np.where(prediction_time < cutoff, "earlier", "later_holdout") gives the two blocks.')),
    Check("holdout summary: episodes and escalations values", values_check(
        HOLDOUT_TABLE, ("episodes", "escalations"),
        "episodes counts the scored episodes in the block and escalations those whose outcome is escalated; the "
        "cutoff is 2026-03-01 00:00 UTC, with < putting the cutoff itself in later_holdout.",
        own=_own_holdout)),
    Check("holdout summary: flagged values", values_check(
        HOLDOUT_TABLE, ("flagged", "flagged_escalations"),
        f"flagged counts the scored episodes whose mean_prev_6h is at least {FLAG_BPM}, and flagged_escalations those "
        "of them that escalated.",
        own=_own_holdout)),
)


def run_checks(root: Path) -> list[tuple[str, str | None]]:
    """Return one (check name, problem or None) pair per check; every check runs."""
    results = []
    for check in CHECKS:
        try:
            check.action(Path(root))
        except (AssertionError, OSError, ValueError, UnicodeDecodeError, csv.Error) as error:
            results.append((check.name, str(error)))
        else:
            results.append((check.name, None))
    return results
